mapper.select:
SELECT lr.LeaveID as leaveId, lr.EmpID as empId, e.EmpName as empName, e.EmpPhone as empPhone, e.Position as position, lr.StoreID as storeId, s.StoreName as storeName, lr.LeaveType as leaveType, lr.StartTime as startTime, lr.EndTime as endTime, lr.ApplyTime as applyTime, lr.ApproverID as approverId, approver.EmpName as approverName, lr.ApproveStatus as approveStatus, lr.ApproveTime as approveTime, lr.LeaveReason as leaveReason FROM leaveRecord lr LEFT JOIN employee e ON lr.EmpID = e.EmpID LEFT JOIN store s ON lr.StoreID = s.StoreID LEFT JOIN employee approver ON lr.ApproverID = approver.EmpID
AND lr.ApproveStatus = #{approveStatus}
AND lr.LeaveType = #{leaveType}
AND e.EmpName LIKE CONCAT('%', #{empName}, '%')
ORDER BY lr.ApplyTime DESC

SELECT StoreID as storeId, StoreName as storeName, StatMonth as statMonth, NewUserCount as newUserCount, TotalOrderCount as totalOrderCount, BeautyOrderCount as beautyOrderCount, FosterOrderCount as fosterOrderCount, MedicalOrderCount as medicalOrderCount, ProductSales as productSales, BeautyRevenue as beautyRevenue, FosterRevenue as fosterRevenue, MedicalRevenue as medicalRevenue, TotalRevenue as totalRevenue, HotServiceType as hotServiceType FROM v_store_monthly_report WHERE StatMonth >= #{startMonth} AND StatMonth <= #{endMonth}
AND StoreID = #{storeId}
ORDER BY StatMonth ASC, StoreID ASC
